struct Step { passed: bool }
fn field_only(steps: &[Step]) -> bool { steps.iter().all(|step| step.passed) }
fn method_call(steps: &[String]) -> bool { steps.iter().all(|step| step.is_empty()) }
fn main() {
    assert!(field_only(&[Step { passed: true }]));
    assert!(!field_only(&[Step { passed: false }]));
    assert!(method_call(&[String::new()]));
    assert!(!method_call(&[String::from("x")]));
}

struct Step { passed: bool }
#[inline(never)]
fn field_only(steps: &[Step]) -> bool { steps.iter().all(|step| step.passed) }
fn main() {
    let empty = std::env::args().nth(1).unwrap() == "empty";
    let steps: &[Step] = if empty { &[] } else { &[Step { passed: false }] };
    let result = field_only(std::hint::black_box(steps));
    assert_eq!(result, empty);
    println!("{result}");
}
